CSS:
.sec{width:1040px;padding:4px 4px 2px;font-family:'Noto Sans CJK KR',sans-serif;font-size:30px;line-height:1.5;color:#1c1c1c;word-break:keep-all}
.sec p{margin:0 0 12px}
.sec b{color:#7a4a17}
.sec .goal{margin:10px 0 14px;padding:14px 20px;border:3px solid #905720;border-radius:12px;font-size:32px;text-align:center}
.sec .rq{margin:8px 0;display:flex;gap:16px;align-items:baseline}
.sec .rq span{flex:none;background:#905720;color:#fff;border-radius:8px;padding:2px 12px;font-size:26px;font-weight:700}
.sec table.kv{width:100%;border-collapse:collapse;margin:4px 0 12px;font-size:28px}
.sec .kv th{width:30%;text-align:left;color:#7a4a17;padding:7px 8px;border-bottom:1px solid #e2d6c6;font-weight:700;vertical-align:top}
.sec .kv td{padding:7px 8px;border-bottom:1px solid #e2d6c6}
.sec figure{margin:10px 0 14px;text-align:center}
.sec img{display:block;margin:0 auto}
.sec figcaption{font-size:25px;margin-top:6px;line-height:1.35;color:#333}
.sec figcaption b{color:#1c1c1c}
.sec .flow{display:flex;gap:10px;margin:8px 0 14px}
.sec .flow div{flex:1;background:#f6efe5;border-radius:10px;padding:10px 8px;text-align:center;font-size:24px;line-height:1.35}
.sec .flow b{display:block;font-size:34px;color:#905720}
.sec .card{border:2px solid #e2d6c6;border-radius:14px;padding:12px 16px 4px;margin:0 0 16px}
.sec .ct{font-weight:700;font-size:32px;color:#905720;margin-bottom:8px}
.sec .nums{display:flex;gap:12px;margin:4px 0 10px}
.sec .num{flex:1;background:#f6efe5;border-radius:10px;padding:10px 12px;text-align:center}
.sec .num .v{font-size:40px;font-weight:700;color:#7a4a17;line-height:1.2}
.sec .num .l{font-size:23px;color:#444;line-height:1.3;margin-top:4px}
.sec .why{font-size:26px;color:#444;background:#faf7f2;border-left:6px solid #905720;padding:8px 12px}
.sec ul{margin:0;padding-left:38px}
.sec li{margin-bottom:10px}
.sec .fr{display:inline-flex;flex-direction:column;align-items:center;line-height:1;vertical-align:middle;font-size:38px}
.sec .fr sup{border-bottom:4px solid #7a4a17;padding:0 10px 3px;vertical-align:baseline;font-size:38px}
.sec .fr span{padding-top:2px}
.sec table.cmp{width:100%;border-collapse:collapse;margin:4px 0 6px;font-size:25px;text-align:center}
.sec .cmp th{background:#905720;color:#fff;padding:5px}
.sec .cmp td{padding:5px;border-bottom:1px solid #e2d6c6}
.sec .cmp td:first-child{text-align:left}
.sec .note{font-size:23px;color:#555;margin:2px 0 10px}
.sec table.ms{width:100%;border-collapse:collapse;margin:6px 0 10px;font-size:25px}
.sec .ms th{background:#905720;color:#fff;padding:5px 8px;font-weight:700}
.sec .ms td{padding:5px 8px;border-bottom:1px solid #e2d6c6}
.sec .row{display:flex;gap:16px;align-items:flex-end}
.sec .row figure{flex:1;margin:6px 0 8px}
.sec .row img{width:100%;height:300px;object-fit:contain}
.sec .prow{display:flex;gap:14px;justify-content:center;align-items:flex-start;margin:6px 0 12px}
.sec .prow figure{margin:0}
.sec .prow img{height:230px;width:auto}
.sec .prow figcaption{font-size:23px}
.sec .pcap{display:flex;justify-content:center;gap:40px;margin:0 0 12px}
.sec .pcap figcaption{font-size:23px}
.sec .ms td:nth-child(2){text-align:center;white-space:nowrap}
.sec .an{font-size:24px;background:#f6efe5;border-radius:10px;padding:8px 12px;margin:0 0 12px;line-height:1.4}
.sec .pipe{display:flex;align-items:center;gap:6px;margin:6px 0 12px}
.sec .pipe div{flex:1;background:#f6efe5;border-radius:10px;padding:8px 4px;text-align:center;font-size:23px;line-height:1.25}
.sec .pipe i{font-style:normal;color:#905720;font-weight:700}
.sec .pipe .o{background:#905720;color:#fff;font-weight:700}
